+  return {
+    logicalVersion: 6,
+    generation: 4,
+    migrations: [
+      {
+        id: "001-replica-schema",
+        sql,
+        checksum: await migrationChecksum(sql),
+        logicalVersion: 3,
+      },
+      {
+        id: "002-annotation-types",
