+    runtime: graph,
+    scopeId: storageKey,
+    generation: await currentGeneration(client),
+    tables: REPLICA_TABLE_BINDINGS,
+    lists: REPLICA_LIST_BINDINGS,
+  });
+  onMemoryStage?.("projector-ready");
+  await markProgress("projector-ready");
