+  return {
+    enter(nextStage: string) {
+      stage = nextStage;
+      sample(nextStage);
+    },
+    sample,
+    finish(): ProcessMemoryReport {
+      clearInterval(sampler);
+      sample("final");
+      return {
+        baseline,
+        peak,
+        rssDeltaBytes: peak.rssBytes - baseline.rssBytes,
+        heapDeltaBytes: peak.heapUsedBytes - baseline.heapUsedBytes,
+        stages,
+        peakStage,
+      };
+    },
+  };
+}
