+  coldCrashLeftNoPartialBatch: boolean;
+  crashRolledBackRowAndCheckpoint: boolean;
+  sqlAndCheckpointCommittedBeforePublication: boolean;
+}
+
+export const restartStatePath = () => `${required("RA11C_MATERIALIZER_OUTPUT")}.state.json`;
