+            {
+                "pid": pid,
+                "baselineRssBytes": int(entry["rssBytes"]),
+                "peakRssBytes": process_peaks.get(pid, int(entry["rssBytes"])),
+                "incrementalRssBytes": (
+                    process_peaks.get(pid, int(entry["rssBytes"]))
+                    - int(entry["rssBytes"])
+                ),
+            }
+            for pid, entry in baseline_processes.items()
+            if entry["kind"] == "renderer"
+        ]
