+  ]);
+  const client = mountedPhase === "memory"
+    ? await PGlite.create({
+        initialMemory: PGLITE_REPLICA_INITIAL_MEMORY,
+        loadDataDir: baseArchive,
+        postgresqlconf: [...PGLITE_REPLICA_POSTGRESQL_CONF],
+      })
