+    ? await PGlite.create({
+        dataDir,
+        initialMemory: PGLITE_REPLICA_INITIAL_MEMORY,
+        loadDataDir: baseArchive,
+        postgresqlconf: [...PGLITE_REPLICA_POSTGRESQL_CONF],
+      })
+    : await PGlite.create({
+        dataDir,
+        initialMemory: PGLITE_REPLICA_INITIAL_MEMORY,
+        postgresqlconf: [...PGLITE_REPLICA_POSTGRESQL_CONF],
+      });
+  onMemoryStage?.("pglite-open");
+  await markProgress("pglite-open");
+  openClients.push(client);
