+      lease,
+      ownership: "held",
+      leaseLifetime: "caller",
+      storageKey: STORAGE_KEY,
+      targets: REPLICA_TARGETS,
+      checkpointShapes: REPLICA_SHAPES.map(({ shape }) => shape),
