+    "scripts/test-ra11c-materialization.py",
+    "web/package.json",
+    "web/pnpm-lock.yaml",
+    "web/public/pglite-base.tgz",
+    "web/ra11c-browser-memory.html",
+    "web/vite.config.ts",
+    "web/src/shared/sync/chunk-writer.ts",
+    "web/src/shared/sync/frf-shape-transport.ts",
+    "web/src/shared/sync/migration-ledger.ts",
+    "web/src/shared/sync/pglite-bootstrap.ts",
+    "web/src/shared/sync/pglite-schema.ts",
+    "web/src/shared/sync/replica-browser-memory.ts",
+    "web/src/shared/sync/replica-mounted-runtime.ts",
+    "web/src/shared/sync/replica-mounted.integration.test.ts",
+    "web/src/shared/sync/replica-runtime.ts",
+    "web/src/shared/sync/replica-wiring.ts",
+    "web/src/shared/sync/replica-worker-owner.ts",
+)
+
+
+def campaign_input_fingerprints() -> dict[str, object]:
+    files: dict[str, dict[str, object]] = {}
+    for relative_path in CAMPAIGN_INPUT_PATHS:
+        content = (ROOT / relative_path).read_bytes()
+        files[relative_path] = {
+            "bytes": len(content),
+            "sha256": hashlib.sha256(content).hexdigest(),
+        }
+    canonical = json.dumps(
+        files, sort_keys=True, separators=(",", ":")
+    ).encode()
+    return {
+        "aggregateSha256": hashlib.sha256(canonical).hexdigest(),
+        "files": files,
+    }
+
+
+def load_base():
+    spec = importlib.util.spec_from_file_location("ra11a_sync_base", BASE_PATH)
+    if spec is None or spec.loader is None:
+        raise RuntimeError("could not load the RA11a stack coordinator")
+    module = importlib.util.module_from_spec(spec)
+    spec.loader.exec_module(module)
+    return module
